// Typed source funding assertions; original award strings remain unchanged.
(ReadFile as function, ArchiveBase as text, ExpectedBatch as text) as list =>
let
    Manifest=Json.Document(ReadFile(ArchiveBase&"/manifest.json")),
    Checked=if Manifest[kind]="publication_award_crosswalk_retention_v1" and Manifest[batch]=ExpectedBatch and Manifest[namespace]="nhmrc" and Manifest[complete]=true then Manifest else error "Crossref award packet identity drift",
    Read=(Name as text) as record => let F=List.Select(Checked[files],each [name]=Name),B=Binary.Buffer(ReadFile(ArchiveBase&"/"&Name)),Valid=List.Count(F)=1 and Binary.Length(B)=F{0}[bytes] in if Valid then Json.Document(B) else error "Crossref award file identity or length drift",
    AuthorityEntries=List.Select(Checked[files],each [name]=Checked[authority][name]),
    Authority=if List.Count(AuthorityEntries)=1 and Checked[authority][sha256]=AuthorityEntries{0}[sha256] then Read(Checked[authority][name]) else error "Crossref authority provenance hash drift",
    AuthorityROR=if List.AnyTrue(List.Transform(Authority[links],each [type]="website" and [value]="https://www.nhmrc.gov.au/")) then Authority[id] else error "Crossref award funder authority drift",
    FunderIDs=List.Buffer(List.Combine(List.Transform(List.Select(Authority[external_ids],each [type]="fundref"),each List.Transform([all],(V)=>"10.13039/"&V)))),
    DOI=(S as text) as text => let T=Text.Lower(Text.Trim(S)),Prefixes={"https://doi.org/","http://doi.org/","https://dx.doi.org/","http://dx.doi.org/"},P=List.First(List.Select(Prefixes,each Text.StartsWith(T,_)),null) in if P=null then T else Text.Range(T,Text.Length(P)),
    Lookups=List.Buffer(List.Transform(Checked[ardc],(Q)=>let D=Read(Q[filename]),F=List.Select(Checked[files],each [name]=Q[filename]),Valid=Q[complete]=true and D[status]="OK" and D[code]="200" and D[data][offset]=0 and D[data][numFound]=List.Count(D[data][records]) and List.Count(F)=1 and Q[sha256]=F{0}[sha256] in if Valid then [Query=Q,Records=List.Buffer(D[data][records])] else error "Incomplete Crossref grant lookup")),
    Rows=List.Combine(List.Transform(Checked[crossref],(Q)=>let D=Read(Q[filename]),W=D[message],P=DOI(Q[doi]),F=List.Select(Checked[files],each [name]=Q[filename]),Valid=D[status]="ok" and DOI(W[DOI])=P and Text.StartsWith(P,"10.") and List.Count(F)=1 and Q[sha256]=F{0}[sha256],Funders=if Valid then Record.FieldOrDefault(W,"funder",{}) else error "Crossref publication identity drift" in List.Combine(List.Transform(Funders,(FR)=>let FID=DOI(Record.FieldOrDefault(FR,"DOI","")),Numbers=if List.Contains(FunderIDs,FID) then Record.FieldOrDefault(FR,"award",{}) else {} in List.RemoveNulls(List.Transform(Numbers,(N)=>let
        Ls=List.Select(Lookups,each [Query][original_identifier]=N),L=if List.Count(Ls)=1 then Ls{0} else null,URI="https://purl.org/au-research/grants/nhmrc/"&N,
        Matches=if L=null then {} else List.Select(L[Records],each Record.FieldOrDefault(_,"type","")="grant" and Record.FieldOrDefault(_,"purl","")=URI and List.Contains(Record.FieldOrDefault(_,"identifiers",{}),N)),
        Provenance=if L=null then "" else Text.FromBinary(Json.FromValue([relationship="explicit_publication_award_identifier",funderDOI=FID,awardNumber=N,ardcRawSHA256=L[Query][sha256],ardcSourceURL=L[Query][url],authorityROR=AuthorityROR,authorityRawSHA256=Checked[authority][sha256]]),TextEncoding.Utf8)
        in if List.Count(Matches)=1 then [EvidenceKey=Text.Combine({"crossref:"&P,"publication_award_crosswalk","doi:"&P,URI},"|"),RelationshipKind="publication_award_crosswalk",SourceWorkID="crossref:"&P,PublicationDOI=P,PublicationPMID="",ReferenceType=Provenance,FromKey="doi:"&P,ToKey=URI,FromLabel=FID,ToLabel=N,ORCID="",ORCIDStatus="Absent",ROR=AuthorityROR,IdentityStatus="Source-supported",SourceURL=Q[url],ObservedUTC=Q[observed_utc],RawSHA256=Q[sha256],SourceVersion=ExpectedBatch,ReviewState="Not reviewed",AuthenticationState="Not authenticated"] else null)))))),
    Output=if List.IsEmpty(Rows) then #table({"EvidenceKey"},{}) else Table.FromRecords(Rows),
    Groups=Table.Group(Output,{"EvidenceKey"},{{"Rows",each Table.Distinct(_),type table}}),
    Result=if List.AllTrue(List.Transform(Groups[Rows],each Table.RowCount(_)=1)) then Table.ToRecords(Table.Distinct(Output,{"EvidenceKey"})) else error "Conflicting repeated Crossref grant assertion"
in List.Buffer(Result)
